'use strict';
/* public/js/70-player.js -- player movement/physics, camera, health and healing. Generated by scripts/split-client.mjs; see ARCHITECTURE.md. */
/* ---------- player update ---------- */
const fwd=new T.Vector3();
function nearCam(x,z,d){return (camera.position.x-x)**2+(camera.position.z-z)**2<d*d}
/* Inside a tent: a small, separate movement update. No gravity, no digging, no outdoor colliders (the room has its
   own tiny furniture colliders instead) - just walk around a flat floor bounded by the room's own walls. Twisters,
   police, Madame Zeroni and lizards all already leave you alone (see inTent() in twPush, and inCamp() elsewhere:
   your x/z never actually change, so every check that already asks "is this in camp?" still says yes). */
function updatePlayerTent(dt){
  const t=TENTS[S.tent];
  let ix=(KEYS['d']||KEYS['arrowright']?1:0)-(KEYS['a']||KEYS['arrowleft']?1:0);
  let iz=(KEYS['w']||KEYS['arrowup']?1:0)-(KEYS['s']||KEYS['arrowdown']?1:0);
  if(touch.id!==null){ix=touch.ix;iz=touch.iz}
  if(uiOpen()||S.inBed!=null){ix=0;iz=0}
  const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw),rx=Math.cos(P.yaw),rz=-Math.sin(P.yaw);
  let mx=fx*iz+rx*ix,mz=fz*iz+rz*ix;const ml=Math.hypot(mx,mz);
  P.moving=false;P.anim=S.inBed!=null?5:0;
  if(ml>0.1&&S.inBed==null){
    mx/=Math.max(1,ml);mz/=Math.max(1,ml);const sp=(P.crouch?2:4.3)*Math.min(1,ml);
    let nx=clamp(P.x+mx*sp*dt,t.x-t.hw+0.5,t.x+t.hw-0.5),nz=clamp(P.z+mz*sp*dt,t.z-t.hd+0.5,t.z+t.hd-0.5);
    for(const c of TENT_COLLIDERS[S.tent]){if(nx>c.x0-0.3&&nx<c.x1+0.3&&nz>c.z0-0.3&&nz<c.z1+0.3){const px=Math.min(nx-(c.x0-0.3),(c.x1+0.3)-nx),pz=Math.min(nz-(c.z0-0.3),(c.z1+0.3)-nz);if(px<pz)nx=nx<(c.x0+c.x1)/2?c.x0-0.3:c.x1+0.3;else nz=nz<(c.z0+c.z1)/2?c.z0-0.3:c.z1+0.3}}
    P.x=nx;P.z=nz;P.fa=Math.atan2(mx,mz);P.moving=true;P.anim=1;
  }
  P.y=TENT_FLOOR_Y;P.vy=0;P.kx=P.kz=0;P.grounded=true;
  me.g.position.set(P.x,P.y,P.z);
  me.g.rotation.x=S.inBed!=null?-Math.PI/2:0;
  if(S.inBed==null){let dr=P.fa-me.g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));me.g.rotation.y+=dr*Math.min(1,dt*14)}
  animPerson(me,P.anim,dt,P.digPh);
  // shelter: water drains slowly just standing around inside, and resting in a bunk restores health and water
  if(S.inBed!=null){S.water=Math.min(waterMax(),S.water+6*dt);S.hp=Math.min(HP_MAX,S.hp+8*dt)}
  else S.water=Math.max(0,S.water-0.15*dt);
  if(S.onionT>0)S.onionT=Math.max(0,S.onionT-dt);
  if(S.zeroT>0)S.zeroT=Math.max(0,S.zeroT-dt);
}
function updatePlayer(dt){
  if(S.ko){S.ko-=dt;downed(dt);animPerson(me,3,dt);if(S.ko<=0)respawn();return}
  if(twSt){twStep(dt);return}   // a twister has you: it drives position/pose/anim entirely, no input
  if(inTent())return updatePlayerTent(dt);
  const trap=isTrapped();
  let ix=(KEYS['d']||KEYS['arrowright']?1:0)-(KEYS['a']||KEYS['arrowleft']?1:0);
  let iz=(KEYS['w']||KEYS['arrowup']?1:0)-(KEYS['s']||KEYS['arrowdown']?1:0);
  if(touch.id!==null){ix=touch.ix;iz=touch.iz}
  if(uiOpen()){ix=0;iz=0}
  const sprint=KEYS['shift']&&S.water>0&&S.carry==null;
  const fx=-Math.sin(P.yaw),fz=-Math.cos(P.yaw),rx=Math.cos(P.yaw),rz=-Math.sin(P.yaw);
  let mx=fx*iz+rx*ix,mz=fz*iz+rz*ix;const ml=Math.hypot(mx,mz);
  const digging=digHeld&&!uiOpen()&&S.carry==null;
  P.moving=false;
  if(digging){
    P.fa=Math.atan2(fx,fz);P.digT+=dt;const iv=0.42;P.digPh=(P.digT%iv)/iv;
    if(P.digT>=iv){P.digT-=iv;scoop()}
    P.anim=2;
  }else{
    P.digT=0.3;
    if(ml>0.1){
      mx/=Math.max(1,ml);mz/=Math.max(1,ml);let sp=(P.crouch?2:sprint?7.2:4.3)*Math.min(1,ml);if(S.carry!=null)sp=Math.min(sp,SIM.carrySpeed(carryN()));
      let nx=P.x+mx*sp*dt,nz=P.z+mz*sp*dt;
      nx=clamp(nx,-HALF+3,HALF-3);nz=clamp(nz,-HALF+3,HALF-3);
      for(const c of colliders){if(nx>c.x0-0.3&&nx<c.x1+0.3&&nz>c.z0-0.3&&nz<c.z1+0.3){const px=Math.min(nx-(c.x0-0.3),(c.x1+0.3)-nx),pz=Math.min(nz-(c.z0-0.3),(c.z1+0.3)-nz);if(px<pz)nx=nx<(c.x0+c.x1)/2?c.x0-0.3:c.x1+0.3;else nz=nz<(c.z0+c.z1)/2?c.z0-0.3:c.z1+0.3}}
      if(trap&&groundAt(nx,nz)-P.y>0.6){nx=P.x;nz=P.z}
      P.x=nx;P.z=nz;P.fa=FP?Math.atan2(fx,fz):Math.atan2(mx,mz);P.moving=true;P.anim=sprint?4:1;
    }else P.anim=0;
  }
  // knockback (a twister throwing you) is now fully handled by twSt/twStep above; P.kx/P.kz are only ever
  // non-zero while that state machine owns the frame, so there's nothing left to integrate here.
  const g=groundAt(P.x,P.z);
  if(KEYS[' ']&&P.grounded&&!P.crouch&&!trap){P.vy=5.6;P.grounded=false}
  P.vy-=16*dt;P.y+=P.vy*dt;
  if(P.y<=g){P.y=g;P.vy=0;P.grounded=true}else if(P.y-g>0.05)P.grounded=P.grounded&&P.y-g<0.3;
  if(P.y<g+0.02)P.grounded=true;
  me.g.position.set(P.x,P.y,P.z);me.g.scale.y=lerp(me.g.scale.y,P.crouch?0.7:1,Math.min(1,dt*10));
  let dr=P.fa-me.g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));me.g.rotation.y+=dr*Math.min(1,dt*14);
  animPerson(me,P.anim,dt,P.digPh);
  if(PARTY.on&&P.anim===0){const beat=PARTY.t*BPM/60;danceArms(me,beat,0);me.g.position.y=P.y+Math.abs(Math.sin(beat*Math.PI))*0.45}
  /* water */
  const drain=P.anim===2?1.05:P.anim===4?1.7:0.5;
  S.water=Math.max(0,S.water-drain*dt*(S.won?0.2:1)*(uiOpen()||PARTY.on?0:1)*(1+haboobF()*HB_DRAIN_MULT));   // a haboob is thirsty work: up to 1.5x drain
  // Out of water used to knock you out on the spot; now it drains health instead (see updateHealth).
  if(S.onionT>0)S.onionT=Math.max(0,S.onionT-dt);
  if(S.zeroT>0)S.zeroT=Math.max(0,S.zeroT-dt);
}
function updateCamera(dt){
  if(FP){camera.position.set(P.x,P.y+(P.crouch?1.0:1.55),P.z);camera.rotation.set(-P.pitch,P.yaw,0,'YXZ');return}
  const cp=Math.cos(P.pitch),dist=inTent()?3.2:5.4;
  let cx=P.x+Math.sin(P.yaw)*dist*cp,cz=P.z+Math.cos(P.yaw)*dist*cp,cy=P.y+1.6+Math.sin(P.pitch)*dist;
  cy=Math.max(cy,(inTent()?TENT_FLOOR_Y:groundAt(cx,cz))+0.5);
  if(inTent())cy=Math.min(cy,TENT_FLOOR_Y+2.2);   // keep the camera under the tent's low ceiling
  const k=1-Math.exp(-dt*14);camera.position.x+=(cx-camera.position.x)*k;camera.position.y+=(cy-camera.position.y)*k;camera.position.z+=(cz-camera.position.z)*k;
  camera.lookAt(P.x,P.y+1.35,P.z);
}
let titleA=0;
function titleCamera(dt){titleA+=dt*0.04;const r=34;camera.position.set(Math.sin(titleA)*r,11,10+Math.cos(titleA)*r);camera.lookAt(0,0,12)}

/* lizards */
function updateLizards(dt,t){
  if(PARTY.on)return;
  const px=P.x,pz=P.z,alive=S.started&&!S.ko;
  for(const L of lizards){
    const tx=L.home.x+Math.cos(t*L.w+L.ph)*5,tz=L.home.z+Math.sin(t*L.w*1.37+L.ph)*5;
    const dp=Math.hypot(px-L.x,pz-L.z);
    let gx,gz,sp;
    if(alive&&S.onionT>0&&dp<7){L.mode='flee';gx=L.x-(px-L.x);gz=L.z-(pz-L.z);sp=4.4}
    // +haboobF()*HB_LIZ_BOOST: bolder in a haboob, bigger detection radius (75-haboob.js)
    else if(alive&&dp<(L.mode==='chase'?11:6.5)+haboobF()*HB_LIZ_BOOST&&!inCamp(px,pz)){if(L.mode!=='chase'){L.mode='chase';logEv('lizChase',{liz:lizards.indexOf(L),x:+L.x.toFixed(1),z:+L.z.toFixed(1),dist:+dp.toFixed(1)});if(dp<12){sfx.hiss();if(Math.random()<0.6)toast('A yellow-spotted lizard is coming for you. Run, or eat an onion.','bad',2600)}}gx=px;gz=pz;sp=4.7}
    else{L.mode='wander';gx=tx;gz=tz;sp=2.3}
    const dx=gx-L.x,dz=gz-L.z,d=Math.hypot(dx,dz);
    if(d>0.05){const s=Math.min(d,sp*dt),nx=L.x+dx/d*s,nz=L.z+dz/d*s;if(!nearCampZone(nx,nz)){L.x=nx;L.z=nz}L.yaw=Math.atan2(dx,dz)}
    L.x=clamp(L.x,-EDGE+2,EDGE-2);L.z=clamp(L.z,-EDGE+2,EDGE-2);
    const g=L.m.g;g.position.set(L.x,groundAt(L.x,L.z)+0.02,L.z);
    g.visible=nearCam(L.x,L.z,LIZARD_DRAW_R);   // PERF: skip drawing far-away lizards (they still move and hunt)
    let dr=L.yaw-g.rotation.y;dr=Math.atan2(Math.sin(dr),Math.cos(dr));g.rotation.y+=dr*Math.min(1,dt*10);
    L.m.tail.rotation.y=Math.sin(t*(L.mode==='wander'?5:14)+L.ph)*0.5;
    if(alive&&L.mode==='chase'&&dp<0.75){sfx.bite();logEv('lizBite',{liz:lizards.indexOf(L),x:+L.x.toFixed(1),z:+L.z.toFixed(1)});knockOut('Bitten','A yellow-spotted lizard bit you.');L.mode='wander'}
  }
}

/* ---------- health ---------- */
/* Health runs 0-100. Damage takes it down, and at 0 you're downed like any other knockout (your sack drops, and
   friends can pick you up). It heals on its own: once you've gone HEAL_DELAY seconds without getting hurt, it comes
   back at HEAL_RATE per second (about a minute from nearly empty to full). Running out of water drains it instead
   of healing it. Lizard bites, the police and Madame Zeroni still knock you out outright. */
const HP_MAX=100,HEAL_DELAY=5,HEAL_RATE=1.5,THIRST_DPS=4,REVIVE_HP=40;
let hurtFx=0;
function hurt(n,title,text){
  if(!S.started||S.ko||n<=0)return;
  S.hp=Math.max(0,S.hp-n);S.hurtT=0;hurtFx=Math.min(1,hurtFx+0.35+n/60);sfx.thud();
  logEv('hurt',{amt:n,hp:Math.round(S.hp),title,text,x:+P.x.toFixed(1),z:+P.z.toFixed(1)});
  if(S.hp<=0)knockOut(title,text);
}
function updateHealth(dt){
  hurtFx=Math.max(0,hurtFx-dt*1.2);$('#hurtFx').style.opacity=hurtFx.toFixed(2);
  if(S.ko)return;
  S.hurtT+=dt;
  if(S.water<=0&&!uiOpen()&&!PARTY.on){
    if(!S.thirsty){S.thirsty=true;toast('You\'re out of water and losing health. Get to Mr. Sir for a refill.','bad',5000)}
    S.hurtT=0;S.hp=Math.max(0,S.hp-THIRST_DPS*dt);hurtFx=Math.max(hurtFx,0.25);
    if(S.hp<=0)knockOut('Heatstroke','You ran out of water in the sun.');
  }else{
    if(S.water>0)S.thirsty=false;
    if(S.hurtT>=HEAL_DELAY)S.hp=Math.min(HP_MAX,S.hp+HEAL_RATE*dt);
  }
}

